#include <iostream>
#include <vector>
#include <algorithm>
#include <ranges>
using namespace std;

int main() {
    vector<int> nums = {5, 2, 8, 1, 3};
    std::sort(nums.begin(), nums.end());

    // C++20 Ranges example
    auto even = nums | std::views::filter([](int n){ return n % 2 == 0; });
    return 0;
}
